import{d as c,C as t,o as u,c as p,j as a,a as r,E as o,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第三十五章","description":"从执大象与往而不害，到道之淡而有用，辨一时感悦与不可穷尽的作用。","frontmatter":{"title":"道德经第三十五章","description":"从执大象与往而不害，到道之淡而有用，辨一时感悦与不可穷尽的作用。","category":"guide","aliases":["道德经第三十五章","老子第三十五章","dao de jing chapter 35"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-35.md","filePath":"daoism/dao-de-jing/chapter-35.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-35.md"},y=c({...b,setup(g){const n=[{id:"holding-the-great-image",label:"执大象，天下往",showLabel:!0,sentences:[[{text:"执",glossary:"zhi"},{text:"大象",glossary:"daxiang"},"，天下往。"]],note:["【白话】持守大道之象，天下便归往于此。这里的大象是对道的称述，不是一件具体可见、可供占有的巨大物象。","【王弼注择要】「大象，天象之母也。」注又说「能包统万物，无所犯伤」，并以「主若执之，则天下往也」说明在上者执守的方向。","【读法】执在此取持守义，与第二十九章固执占持分开。大象不能直接当成体型大的动物，也不直接等同于易经的某个卦象。"]},{id:"approaching-without-harm",label:"往而不害，安平太",showLabel:!0,sentences:[["往而不害，安平",{text:"太",glossary:"tai"},"。"]],note:["【白话】归往而不受伤害，于是安宁、平和、通泰。前一句所说天下归往，随即由不害限定其条件与结果。","【王弼注择要】「无形无识，不徧不彰，故万物得往而不害妨也。」王弼用不偏、不显彰说明能够容纳万物，使其归往而不被伤害妨碍。","【读法】太本页按通泰、安泰理解，所据录文作大。天下往不能脱离不害读作招揽控制天下的技巧；无识等字在此也不宜直接套入现代认知障碍的意思。"]},{id:"music-and-food-attract-travelers",label:"乐与饵，过客止",showLabel:!0,sentences:[[{text:"乐",glossary:"yue"},"与",{text:"饵",glossary:"er"},"，过客止。"]],note:["【白话】音乐与美食，能使路过的人停下脚步。这里举出可直接悦耳适口、吸引人的事物，为下文道的平淡作对照。","【王弼注择要】「乐与饵应时感悦人心也」，又说「乐与饵则能令过客止」。注指出这种感悦来得直接，能促成一时驻足。","【读法】乐读 yuè，指音乐；饵指食物、美食，不在这里按诱骗的饵料理解。本章借感悦作对照，并未要求一概拒绝音乐与饮食。"]},{id:"plain-speech-and-inexhaustible-use",label:"用之不足既",showLabel:!0,sentences:[["道之",{text:"出口",glossary:"chukou"},"，淡乎其无味，视之不足见，听之不足闻，用之不足",{text:"既",glossary:"ji"},"。"]],note:["【白话】道表达为言说，淡泊得仿佛没有滋味；看它，不足以悦目，听它，不足以娱耳，然而运用起来却不能穷尽。它的价值不只由第一眼、第一耳的感受衡量。","【王弼注择要】「道之出言淡然无味」，又分别说「不足以悦其目」「不足以娱其耳」，最后说「用之不可穷极也」。本页据此将视听之淡与作用之不尽对读。","【读法】出口依出言理解；既作尽。不足见、不足闻既连道之难由感官把握，也循本段王注说明不以悦目娱耳见长，不把不足既误译成不值得使用。"]}],i=[{id:"zhi",term:"执",sense:2},{id:"daxiang",term:"大象",sense:1},{id:"tai",term:"太",sense:1},{id:"yue",term:"乐",sense:2,pinyin:"yuè"},{id:"er",term:"饵",sense:1},{id:"chukou",term:"出口",sense:1},{id:"ji",term:"既",sense:1}];return(x,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),p("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三十五章",tabindex:"-1"},[r("道德经第三十五章 "),a("a",{class:"header-anchor",href:"#道德经第三十五章","aria-label":'Permalink to "道德经第三十五章"'},"​")],-1)),o(s,{title:"道的言说平淡，为什么用之不尽",summary:"本章先说执大象可以使天下归往而不受伤害，再以音乐、美食使过客停步为对照。道的言说虽淡、难以悦耳娱目，其作用却不能穷尽。",points:[{label:"先读",text:"大象在这里连道理解，归往的前提是往而不害、安平太。"},{label:"再辨",text:"乐与饵使人一时停步，用来衬出道的言说不以感官吸引见长。"},{label:"后看",text:"无味、难见难闻与用之不足既对照，落点在作用不可穷尽。"}],hint:"乐与饵的乐读 yuè，与第三十一章乐杀人的 lè 分义；既在本章取尽义，太按通泰理解。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[r("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:n,glossary:i}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[r("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"往而不害，安平太。",tone:"归往应以不害为前提",guide:"看归往的结果是否使人安宁通泰，而不只看聚集了多少人。"},{text:"乐与饵，过客止。",tone:"感悦使人暂驻",guide:"理解音乐、美食的直接吸引，再与道的平淡和长久作用对读。"},{text:"道之出口，淡乎其无味，视之不足见，听之不足闻，用之不足既。",tone:"平淡而作用不尽",guide:"不凭热闹与新鲜感判断全部价值，也不把平淡本身当作正确的保证。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[r("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:i}),e[4]||(e[4]=m("",15))])}}});export{_ as __pageData,y as default};
